compare_loop.go.src:
package main

import "fmt"

func same(a, b []int) bool {
	if len(a) != len(b) {
		return false
	}
	for i := range a {
		if a[i] != b[i] {
			return false
		}
	}
	return true
}

func main() {
	fmt.Println(same([]int{1, 2}, []int{1, 2}))
	fmt.Println(same([]int{1, 2}, []int{2, 1}))
	fmt.Println(same([]int{1, 2}, []int{1, 2, 3}))
}

